// Module-level constant and helper:
const KNOWN_MODULE_EXTENSIONS = ['.ts', '.tsx', '.js', '.mjs', '.cjs'] as const;

function resolveRelativeModuleTarget(target: string, sourceFileRelPosix: string): string {
  if (!target.startsWith('.')) return target;
  let resolved = path.posix.normalize(path.posix.join(path.posix.dirname(sourceFileRelPosix), target));
  if (!KNOWN_MODULE_EXTENSIONS.some((ext) => resolved.endsWith(ext))) {
    resolved = `${resolved}.ts`;
  }
  return resolved;
}

// In the import branch:
if (target.startsWith('.')) {
  targetRel = resolveRelativeModuleTarget(target, relPosix);
}

